mapper.select:
select from lab_task t left join lab_member lm on lm.id=t.owner_id and lm.del_flag='0' left join sys_user u on u.user_id=lm.user_id and u.del_flag='0' where t.del_flag='0' and t.id=#{id}and t.parent_id=#{parentId} and t.goal_id=#{goalId}and t.milestone_id=#{milestoneId} and t.task_level=#{taskLevel}
and ((t.task_level='month' and t.period=#{period}) or (t.task_level='week' and exists(select 1 from lab_task period_parent where period_parent.id=t.parent_id and period_parent.task_level='month' and period_parent.period=#{period} and period_parent.del_flag='0')))
and t.period=#{period}
and ((t.task_level='month' and t.period<=#{periodTo}) or (t.task_level='week' and exists(select 1 from lab_task period_to_parent where period_to_parent.id=t.parent_id and period_to_parent.task_level='month' and period_to_parent.period<=#{periodTo} and period_to_parent.del_flag='0')))
and t.biz_line=#{bizLine} and t.task_type=#{taskType} and t.owner_id=#{ownerId}and t.dept_id=#{deptId} and t.workflow_status=#{workflowStatus}
and t.workflow_status in #{workflowStatus}
and t.result_status=#{resultStatus} and t.title like concat('%',#{title},'%') and t.current_block_flag=#{currentBlockFlag}
and exists(select 1 from lab_task_block_event be where be.task_id=t.id and be.block_status='OPEN' and be.del_flag='0' and date(be.block_start_time)<=date(#{blockStartBefore}))
and t.period_lock_flag='0' and not exists(select 1 from lab_period_close pc where pc.period=case when t.task_level='week' then (select close_parent.period from lab_task close_parent where close_parent.id=t.parent_id and close_parent.del_flag='0') else t.period end and pc.close_status='CLOSED' and pc.del_flag='0') and (t.plan_date<date(#{asOf}) or t.plan_date is null or t.deliverable is null or trim(t.deliverable)='' or (t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')<>'UNDONE' and (t.actual_finish_time is null or t.result_desc is null or trim(t.result_desc)='' or not exists(select 1 from lab_task_evidence pe where pe.task_id=t.id and pe.del_flag='0'))) or (t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')='UNDONE' and (t.fail_reason is null or trim(t.fail_reason)='' or t.next_action is null or trim(t.next_action)='')) or (t.coordination_required='1' and (t.coordination_owner_id is null or t.coordination_dept_id is null or t.coordination_content is null or trim(t.coordination_content)='' or t.coordination_support is null or trim(t.coordination_support)='')))
order by t.period desc,t.plan_date,t.id
